import json,copy
from pathlib import Path
R=Path('.')
def read(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def save(p,d):(R/p).write_text(json.dumps(d,indent=2,ensure_ascii=True)+'\n',encoding='utf-8')
def route(v):return '/pages/features?view='+v
def section(title,body='',eye='QUADRATUM',h='h2',dark=False,art=None,label='',link='',label2='',link2='',cards=None):
 s={'type':'editorial-story','settings':{'layout':'hero' if art else 'text','heading':title,'heading_tag':h,'body':body,'eyebrow':eye,'background':'#0A0A0A' if dark else '#F5F5F3','foreground':'#F5F5F3' if dark else '#0A0A0A','label':label,'link':link,'label_two':label2,'link_two':link2}}
 if art:s['settings']['brand_art']='quadratum-'+art+'.png'
 if cards:s['blocks']={f'c{i}':{'type':'story','settings':v} for i,v in enumerate(cards)};s['block_order']=list(s['blocks'])
 return s
def card(title,text,link,label='Explore',eye='DESIGNED AROUND YOU',image=''):return dict(title=title,text=text,link=link,label=label,eyebrow=eye,image=image)
def page(*sections):return {'sections':{f's{i}':s for i,s in enumerate(sections)},'order':[f's{i}' for i in range(len(sections))]}
def writepage(v,*ss):save('templates/page.'+v+'.json',page(*ss))
